package solution

import "strings"

func SplitEscaped(x string) ([]string, bool) {
	if x == "" {
		return []string{}, false
	}

	var result []string
	var current string
	inEscape := false

	for i := 0; i < len(x); i++ {
		c := x[i]

		if inEscape {
			if c == '\\' {
				inEscape = false
			} else {
				current += string(c)
			}
		} else if c == '\\' {
			inEscape = true
		} else if c == ',' {
			if inEscape {
				// Escaped comma, ignore it
				continue
			}
			// Unescaped comma
			result = append(result, current)
			current = ""
		} else {
			current += string(c)
		}
	}

	// Handle trailing backslash
	if inEscape {
		// Trailing backslash without a following character means failure
		return nil, false
	}

	// Handle trailing backslash at end of string
	if current == "\\" {
		return nil, false
	}

	// Handle trailing backslash followed by non-escape character
	if current == "\\" && len(x) > i+1 && x[i+1] != '\\' {
		return nil, false
	}

	// Handle trailing backslash at end of string
	if current == "\\" {
		return nil, false
	}

	// If we are still in escape mode at the end, it's a failure
	if inEscape {
		return nil, false
	}

	return result, true
}

